arguments.command:
python -c "
from alphacrafter.sim.utils import get_index_daily_data
for sym in ['VIX', 'DXY']:
    try:
        df = get_index_daily_data(sym, days=30)
        if df is not None and len(df) > 0:
            close = df['close'].to_numpy(float)
            last = close[-1]
            d20 = close[-21] if len(close) >= 21 else close[0]
            print(f'{sym}: last={last:.2f} 20d_chg={100*(last/d20-1):+.2f}%')
        else:
            print(f'{sym}: no data')
    except Exception as e:
        print(f'{sym}: err {e}')
"

